package dk.sdu.cbse.gamelab; public final class EnemyComponent implements IGamePluginService,IEntityProcessingService{public void start(GameData d){Entity e=new Entity("ENEMY",100,100,16);e.health=3;d.entities.add(e);}public void stop(GameData d){d.entities.removeIf(e->e.type.equals("ENEMY"));}public void process(GameData d,double dt){Entity p=d.entities.stream().filter(e->e.type.equals("PLAYER")).findFirst().orElse(null);if(p==null)return;for(Entity e:d.entities.stream().filter(x->x.type.equals("ENEMY")).toList()){double a=Math.atan2(p.y-e.y,p.x-e.x);e.rotation=Math.toDegrees(a);e.x+=Math.cos(a)*45*dt;e.y+=Math.sin(a)*45*dt;d.wrap(e);}}}